function quickReply(text, actions = []) {
  const message = { type: 'text', text };
  if (actions.length) {
    message.quickReply = {
      items: actions.slice(0, 13).map(([label, value]) => ({
        type: 'action',
        action: { type: 'message', label, text: value },
      })),
    };
  }
  return [message];
}

function reply(base, text, actions = []) {
  return { ...base, action: 'reply', messages: quickReply(text, actions) };
}

function twParts() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date());
  return Object.fromEntries(parts.map(part => [part.type, part.value]));
}

function formatIso(year, month, day) {
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return null;
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function twDate(offset = 0) {
  const parts = twParts();
  const date = new Date(Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day) + offset));
  return date.toISOString().slice(0, 10);
}

function parseDate(text) {
  let remaining = text;
  let match = remaining.match(/\b(20\d{2})[-\/.](\d{1,2})[-\/.](\d{1,2})\b/);
  if (match) {
    const date = formatIso(Number(match[1]), Number(match[2]), Number(match[3]));
    if (date) return { date, remaining: remaining.replace(match[0], ' ') };
  }

  match = remaining.match(/(?:^|\s)(\d{1,2})[\/.](\d{1,2})(?:\s|$)/);
  if (!match) match = remaining.match(/(\d{1,2})月(\d{1,2})日/);
  if (match) {
    const year = Number(twParts().year);
    const date = formatIso(year, Number(match[1]), Number(match[2]));
    if (date) return { date, remaining: remaining.replace(match[0], ' ') };
  }

  for (const [word, offset] of [['前天', -2], ['昨天', -1], ['今天', 0]]) {
    if (remaining.includes(word)) return { date: twDate(offset), remaining: remaining.replace(word, ' ') };
  }
  return { date: twDate(0), remaining };
}

function removeAt(text, index, length) {
  return `${text.slice(0, index)} ${text.slice(index + length)}`;
}

function parsePayment(text) {
  const lower = text.toLowerCase();
  for (const [alias, payment] of paymentAliases) {
    const index = lower.indexOf(alias.toLowerCase());
    if (index >= 0) return { payment, remaining: removeAt(text, index, alias.length) };
  }
  return { payment: '', remaining: text };
}

function evaluateAmount(expression) {
  const clean = expression.replace(/,/g, '').replace(/\s/g, '');
  if (!/^\d+(?:\.\d+)?(?:[+-]\d+(?:\.\d+)?)*$/.test(clean)) return null;
  const tokens = clean.match(/[+-]?\d+(?:\.\d+)?/g) || [];
  const amount = tokens.reduce((sum, token) => sum + Number(token), 0);
  return Number.isFinite(amount) && amount > 0 ? Math.round(amount * 100) / 100 : null;
}

function parseAmount(text) {
  if (/\d\s*[+-]\s*[+-]\s*\d/.test(text)) return { amount: null, remaining: text, invalid: true };
  const matches = [...text.matchAll(/\d[\d,]*(?:\.\d+)?(?:\s*[+-]\s*\d[\d,]*(?:\.\d+)?)*/g)];
  for (let index = matches.length - 1; index >= 0; index -= 1) {
    const match = matches[index];
    const amount = evaluateAmount(match[0]);
    if (amount !== null) {
      return { amount, remaining: removeAt(text, match.index, match[0].length), invalid: false };
    }
  }
  return { amount: null, remaining: text, invalid: false };
}

function detectCategory(text) {
  const lower = text.toLowerCase();
  const candidates = [];
  for (const [category, keywords] of Object.entries(categoryKeywords)) {
    for (const keyword of keywords) candidates.push([keyword.toLowerCase(), category]);
  }
  candidates.sort((a, b) => b[0].length - a[0].length);
  const found = candidates.find(([keyword]) => lower.includes(keyword));
  return found?.[1] || '';
}

function categoryPrompt(base, pending, intro = '請選擇分類群組：') {
  pending.waiting = 'category';
  pending.updatedAt = Date.now();
  store.pending[base.userId] = pending;
  const actions = Object.keys(categoryGroups).map(group => [group, `分類群組:${group}`]);
  actions.push(['❌ 取消', '取消記帳']);
  return reply(base, intro, actions);
}

function paymentPrompt(base, pending, intro = '請選擇付款方式：') {
  pending.waiting = 'payment';
  pending.updatedAt = Date.now();
  store.pending[base.userId] = pending;
  const actions = payments.map(payment => [payment, `付款:${payment}`]);
  actions.push(['❌ 取消', '取消記帳']);
  return reply(base, intro, actions);
}

function amountPrompt(base, pending, intro = '請輸入金額，例如：120 或 100+50') {
  pending.waiting = 'amount';
  pending.updatedAt = Date.now();
  store.pending[base.userId] = pending;
  return reply(base, intro, [['❌ 取消', '取消記帳']]);
}

function confirmPrompt(base, pending) {
  pending.waiting = 'confirm';
  pending.updatedAt = Date.now();
  store.pending[base.userId] = pending;
  const amount = new Intl.NumberFormat('zh-TW', { maximumFractionDigits: 2 }).format(pending.amount);
  const text = [
    '📝 請確認記帳', '',
    `📅 日期：${pending.date}`,
    `📂 分類：${pending.category}`,
    `💰 金額：NT$${amount}`,
    `💳 付款：${pending.payment}`,
    `✏️ 備註：${pending.note || '（無）'}`,
  ].join('\n');
  return reply(base, text, [
    ['✅ 確認', '確認記帳'], ['📂 改分類', '修改分類'], ['💰 改金額', '修改金額'],
    ['💳 改付款', '修改付款'], ['❌ 取消', '取消記帳'],
  ]);
}

function nextStep(base, pending) {
  if (!pending.amount) return amountPrompt(base, pending);
  if (!pending.category) return categoryPrompt(base, pending);
  if (!pending.payment) return paymentPrompt(base, pending);
  return confirmPrompt(base, pending);
}

function handle(input) {
  const base = {
    userId: input.userId || '',
    replyToken: input.replyToken || '',
    webhookEventId: input.webhookEventId || '',
  };
  const message = String(input.message || '').trim();
  if (!base.userId || !base.replyToken || !message) return null;

  let pending = store.pending[base.userId];

  if (message === '取消記帳') {
    delete store.pending[base.userId];
    return reply(base, '已取消這筆記帳。');
  }

  if (message === '記帳' || message === '記帳說明') {
    return reply(base, [
      '請在「記帳」後輸入一整句，例如：',
      '• 記帳 午餐120現金',
      '• 記帳 昨天中油1350玉山卡',
      '• 記帳 8/1 停車60 line',
      '',
      '日期可省略；付款方式省略時會沿用上次成功記帳的方式。',
    ].join('\n'));
  }

  if (message === '確認記帳') {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    if (pending.saving) return reply(base, '這筆資料正在寫入，請稍候，不需要重複確認。');
    if (!pending.amount || !pending.category || !pending.payment) return nextStep(base, pending);
    pending.saving = true;
    pending.updatedAt = Date.now();
    store.pending[base.userId] = pending;
    return {
      ...base,
      action: 'save',
      title: String(pending.note || pending.category).slice(0, 100),
      note: String(pending.note || '').slice(0, 100),
      category: pending.category,
      amount: pending.amount,
      payment: pending.payment,
      date: pending.date,
    };
  }

  if (message.startsWith('分類群組:')) {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    const group = message.slice('分類群組:'.length).trim();
    const options = categoryGroups[group];
    if (!options) return categoryPrompt(base, pending, '找不到這個群組，請重新選擇：');
    const actions = options.map(category => [category, `類別:${category}`]);
    actions.push(['❌ 取消', '取消記帳']);
    return reply(base, `請選擇「${group}」的細分類：`, actions);
  }

  if (message.startsWith('類別:')) {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    const category = message.slice('類別:'.length).trim();
    if (!categories.includes(category)) return categoryPrompt(base, pending, '分類不在允許清單，請重新選擇：');
    pending.category = category;
    pending.updatedAt = Date.now();
    return nextStep(base, pending);
  }

  if (message.startsWith('付款:')) {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    const payment = message.slice('付款:'.length).trim();
    if (!payments.includes(payment)) return paymentPrompt(base, pending, '付款方式不在允許清單，請重新選擇：');
    pending.payment = payment;
    pending.updatedAt = Date.now();
    return nextStep(base, pending);
  }

  if (message === '修改分類') {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    return categoryPrompt(base, pending);
  }
  if (message === '修改付款') {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    return paymentPrompt(base, pending);
  }
  if (message === '修改金額') {
    if (!pending) return reply(base, '這筆待確認資料已過期，請重新輸入「記帳 …」。');
    return amountPrompt(base, pending);
  }

  if (pending?.waiting === 'amount') {
    const parsed = parseAmount(message);
    if (!parsed.amount || parsed.invalid) return amountPrompt(base, pending, '金額格式不正確，請輸入例如：120 或 100+50');
    pending.amount = parsed.amount;
    pending.updatedAt = Date.now();
    return nextStep(base, pending);
  }

  if (pending?.waiting === 'category') {
    const category = categories.includes(message) ? message : detectCategory(message);
    if (!category) return categoryPrompt(base, pending, '無法辨識分類，請從群組選擇：');
    pending.category = category;
    pending.updatedAt = Date.now();
    return nextStep(base, pending);
  }

  if (pending?.waiting === 'payment') {
    const parsed = parsePayment(message);
    if (!parsed.payment) return paymentPrompt(base, pending, '無法辨識付款方式，請重新選擇：');
    pending.payment = parsed.payment;
    pending.updatedAt = Date.now();
    return nextStep(base, pending);
  }

const content = message.startsWith('記帳')
  ? message.slice(2).replace(/^[\s:：]+/, '').trim()
  : message;
  if (!content) return reply(base, '請輸入完整內容，例如：記帳 午餐120現金');

  const parsedDate = parseDate(content);
  const parsedPayment = parsePayment(parsedDate.remaining);
  const parsedAmount = parseAmount(parsedPayment.remaining);
  const category = detectCategory(parsedAmount.remaining);
  const note = parsedAmount.remaining
    .replace(/[，,；;|]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 100);

  pending = {
    date: parsedDate.date,
    category,
    amount: parsedAmount.amount,
    payment: parsedPayment.payment || store.lastPayment[base.userId] || '',
    note,
    updatedAt: Date.now(),
    waiting: '',
    saving: false,
  };
  store.pending[base.userId] = pending;

  if (parsedAmount.invalid) return amountPrompt(base, pending, '金額格式不正確，請輸入例如：120 或 100+50');
  return nextStep(base, pending);
}

const output = [];
for (const [index, item] of $input.all().entries()) {
  const result = handle(item.json);
  if (result) output.push({ json: result, pairedItem: { item: index } });
}
return output;

